const opType = msg.operationType || 'read';

if (opType === 'write') {
    return [null, msg];
} else {
    return [msg, null];
}

flow.set("itc_rpc_response_topic", msg.rpcResponseTopic);
flow.set("itc_write_result", msg.writeResult || null);

return msg;

msg.payload = {
    fc: 3,
    unitid: 1,
    address: 162,
    quantity: 3
};
return msg;

let raw = msg.payload;
let data = raw;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

if (typeof raw === "string" || !Array.isArray(data) || data.length < 3) {
    node.error("Invalid modbus response");
    return null;
}

const gatewayId = global.get("GATEWAY_ID") || env.get("GATEWAY_ID") || "EC100-GW-001";

const reg162 = data[0];
const reg163 = data[1];
const reg164 = data[2];

// Unpack bytes
const year = (reg162 >> 8) & 0xFF;      // High byte
const month = reg162 & 0xFF;            // Low byte
const day = (reg163 >> 8) & 0xFF;       // High byte
const hour = reg163 & 0xFF;             // Low byte
const minute = (reg164 >> 8) & 0xFF;    // High byte
const second = reg164 & 0xFF;           // Low byte

// Build ISO timestamp (year is 2000-based)
const fullYear = 2000 + year;
const timestamp = new Date(
    fullYear,
    month - 1,  // JavaScript months are 0-based
    day,
    hour,
    minute,
    second
).toISOString();

const state = {
    kind: "InverterTimeConfigState",
    timestampUtc: new Date().toISOString(),
    gatewayId: gatewayId,
    version: 1,

    systemTime: {
        year: year,
        month: month,
        day: day,
        hour: hour,
        minute: minute,
        second: second
    },

    localtimestamp: timestamp
};

const writeResult = flow.get("itc_write_result");
const rpcResponseTopic = flow.get("itc_rpc_response_topic");

flow.set("itc_write_result", null);
flow.set("itc_rpc_response_topic", null);

if (writeResult) {
    msg.payload = {
        success: writeResult.success,
        message: writeResult.message,
        state: state
    };
} else {
    msg.payload = state;
}

msg.state = state;
msg.rpcResponseTopic = rpcResponseTopic;

node.status({ fill: "green", shape: "dot", text: `${fullYear}-${month.toString().padStart(2,'0')}-${day.toString().padStart(2,'0')} ${hour.toString().padStart(2,'0')}:${minute.toString().padStart(2,'0')}:${second.toString().padStart(2,'0')}` });

return msg;

if (!msg.rpcResponseTopic) {
    return null;
}

msg.topic = msg.rpcResponseTopic;
return msg;

const params = msg.rpcParams || {};
let time = params.systemTime;

// Store RPC topic
global.set("itc_write_rpc_topic", msg.rpcResponseTopic);

// If no systemTime provided, use current time
if (!time || Object.keys(time).length === 0) {
    const now = new Date();
    time = {
        year: now.getFullYear() - 2000,  // Convert to 2000-based
        month: now.getMonth() + 1,       // JavaScript months are 0-based
        day: now.getDate(),
        hour: now.getHours(),
        minute: now.getMinutes(),
        second: now.getSeconds()
    };
}

// Pack bytes into 3 registers
const reg162 = ((time.year & 0xFF) << 8) | (time.month & 0xFF);
const reg163 = ((time.day & 0xFF) << 8) | (time.hour & 0xFF);
const reg164 = ((time.minute & 0xFF) << 8) | (time.second & 0xFF);

// Write all 3 registers at once using FC16
msg.payload = {
    fc: 16,
    unitid: 1,
    address: 162,
    quantity: 3,
    value: [reg162, reg163, reg164]
};

msg.timeToWrite = time;

const fullYear = 2000 + time.year;
node.status({ fill: "yellow", shape: "dot", text: `Writing: ${fullYear}-${time.month}-${time.day} ${time.hour}:${time.minute}:${time.second}` });

return msg;

const time = msg.timeToWrite;
const rpcTopic = global.get("itc_write_rpc_topic");

global.set("itc_write_rpc_topic", null);

const fullYear = 2000 + time.year;
const timeStr = `${fullYear}-${time.month.toString().padStart(2,'0')}-${time.day.toString().padStart(2,'0')} ${time.hour.toString().padStart(2,'0')}:${time.minute.toString().padStart(2,'0')}:${time.second.toString().padStart(2,'0')}`;

const finalMsg = {
    writeResult: {
        success: true,
        message: `Successfully set inverter time to ${timeStr}`
    },
    rpcResponseTopic: rpcTopic
};

node.status({ fill: "green", shape: "dot", text: `Write OK: ${timeStr}` });

// Trigger read after write
return finalMsg;
